css:
@font-face{font-family:'PF';font-weight:900;src:url(node_modules/@fontsource/playfair-display/files/playfair-display-latin-900-normal.woff2)}
@font-face{font-family:'PF';font-weight:700;src:url(node_modules/@fontsource/playfair-display/files/playfair-display-latin-700-normal.woff2)}
@font-face{font-family:'LF';font-weight:500;src:url(node_modules/@fontsource/libre-franklin/files/libre-franklin-latin-500-normal.woff2)}
@font-face{font-family:'LF';font-weight:800;src:url(node_modules/@fontsource/libre-franklin/files/libre-franklin-latin-800-normal.woff2)}
@font-face{font-family:'UF';font-weight:700;src:url(node_modules/@fontsource/unifrakturcook/files/unifrakturcook-latin-700-normal.woff2)}
.card{background:#F2ECDD;color:#151412;font-family:'LF';
 background-image:radial-gradient(rgba(0,0,0,.06) 1.2px,transparent 1.3px);background-size:9px 9px}
.safe{justify-content:flex-start}
.mast{border-top:10px solid #151412;border-bottom:3px solid #151412;padding:14px 0 10px;text-align:center;margin-bottom:10px}
.mast b{font:700 82px/1 'UF';display:block}
.dateline{display:flex;justify-content:space-between;font:800 30px 'LF';letter-spacing:2px;text-transform:uppercase;border-bottom:3px solid #151412;padding:10px 0 12px;margin-bottom:46px}
h1{font:900 120px/1.0 'PF';margin:0 0 30px;letter-spacing:-2px}
h2{font:900 96px/1.02 'PF';margin:0 0 28px;letter-spacing:-1px}
.deck{font:700 italic 54px/1.2 'PF';margin:0 0 30px;border-left:12px solid #C8201E;padding-left:26px}
p.b{font:500 48px/1.32 'LF';margin:0 0 30px}
p.b strong{font-weight:800;background:linear-gradient(transparent 58%,#F4C542 58%)}
.stamp{display:inline-block;align-self:flex-start;border:7px solid #C8201E;color:#C8201E;font:800 44px 'LF';letter-spacing:4px;padding:8px 22px;transform:rotate(-4deg);margin:0 0 36px}
.big{font:900 230px/0.9 'PF';margin:0;color:#C8201E}
.chain{display:flex;flex-direction:column;gap:0}
.node{border:5px solid #151412;background:#FFFDF6;padding:20px 28px;font:800 52px/1.15 'LF';box-shadow:10px 10px 0 #151412}
.node span{display:block;font:500 42px/1.25 'LF';margin-top:6px}
.arr{font:900 64px/1 'PF';text-align:center;margin:12px 0}
.cols{display:grid;grid-template-columns:1fr 1fr;gap:36px;border-top:3px solid #151412;padding-top:30px}
.cols div{font:500 46px/1.3 'LF'}
.cols div b{display:block;font:900 66px/1.05 'PF';margin-bottom:10px}
.card-1{background:#151412;color:#F2ECDD;background-image:radial-gradient(rgba(255,255,255,.07) 1.2px,transparent 1.3px);background-size:9px 9px}
.card-1 .mast,.card-1 .dateline{border-color:#F2ECDD}
.card-1 h1{font-size:150px;line-height:.98}
.card-1 h1 em{color:#F4C542;font-style:normal}
.handle{font:800 54px 'LF';margin-top:24px;background:#151412;color:#F2ECDD;padding:20px 26px;align-self:flex-start}

.safe{justify-content:flex-start}
.body{flex:1;display:flex;flex-direction:column;justify-content:center;padding-bottom:40px}
h2{font-size:112px}
p.b{font-size:58px;line-height:1.28}
.big{font-size:260px;line-height:1;margin:0 0 20px}
.node{font-size:64px;padding:26px 34px}
.node span{font-size:50px}
.arr{font:800 80px/1 'LF';margin:18px 0}
.deck{font-size:60px}
.stamp{font-size:50px}
.card-1 h1{font-size:160px}
.handle{font-size:58px}
